import React from "react";

import "./App.css";

const App = () => {
    return (
        <>
            <h1>Tic Tac Toe</h1>
            <div className='App'>
                <div className='board'>
                    <div className='row'>
                        <div className='square'>X</div>
                        <div className='square'>O</div>
                        <div className='square'>X</div>
                    </div>
                    <div className='row'>
                        <div className='square'>O</div>
                        <div className='square'>X</div>
                        <div className='square'>O</div>
                    </div>
                    <div className='row'>
                        <div className='square'>X</div>
                        <div className='square'>O</div>
                        <div className='square'>X</div>
                    </div>
                </div>
            </div>
        </>
    );
};

export default App;
